/*
 * ONE CACHED LESSON, FOR THE CALLER'S OWN LEARNER (TASK-L170 §1).
 *
 * The learner id comes from `Caller learner` — the session — and NEVER from an
 * argument: an optional scope is one forgotten check away from serving anybody's
 * lesson to anybody (L91). `conceptId` only says WHICH of their own lessons.
 *
 * The product's delivery gate is ported, not skipped: a lesson is served only
 * for a live step on the learner's live path that is not locked (a locked step
 * is 403 in the product). Everything else — no learner, no path, not on it,
 * locked, not written yet — answers `rows: []`, one shape, so a caller cannot
 * tell "not yours" from "not there" (the mcp/auth.ts rule).
 *
 * Two producers feed this node (the helper's `learnerId`, the Request's
 * `conceptId`), so it guards both and a late value re-runs it (rule 2). Each
 * arrives exactly once per request, so it answers exactly once.
 */
/* Every read is `{ plain: true }` (OpenNoodl HLT-022): the row as it was saved,
   `objectId` on it, nested documents untouched. A default read turns each nested
   object into a Model with a generated id, which broke a lesson's section ids. */
if (Inputs.learnerId !== undefined && Inputs.conceptId !== undefined) {
  (async () => {
    try {
      const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
      const learnerId = String(Inputs.learnerId);
      const conceptId = String(Inputs.conceptId || '');
      let rows = [];
      if (learnerId && conceptId) {
        const [paths, lessons] = await Promise.all([
          q('LearningPath', { learnerId: { equalTo: learnerId } }),
          // The neutral filter takes ONE key; two conditions are an `and` (live refuses a two-key object).
          q('Lesson', { and: [{ learnerId: { equalTo: learnerId } }, { conceptId: { equalTo: conceptId } }] })
        ]);
        const live = [...paths].sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1))[0];
        const steps = live ? await q('PathStep', { and: [{ pathId: { equalTo: live.pathId } }, { conceptId: { equalTo: conceptId } }] }) : [];
        const step = steps.find((s) => (s.removedAt === undefined || s.removedAt === null) && s.status !== 'locked');
        if (step && lessons.length) {
          // One cached lesson per (learner, concept) here; if a regeneration
          // ever leaves two, the newest generation is the one being served.
          const lesson = [...lessons].sort((a, b) => (b.generationVersion ?? 0) - (a.generationVersion ?? 0))[0];
          rows = [{
            conceptId: lesson.conceptId, title: lesson.title, hook: lesson.hook, landing: lesson.landing,
            conceptVersion: lesson.conceptVersion, projectContextVersion: lesson.projectContextVersion,
            generationVersion: lesson.generationVersion, generatedByTier: lesson.generatedByTier,
            sections: lesson.sections, steps: lesson.steps
          }];
        }
      }
      Outputs.rows = rows;
      Outputs.done();
    } catch (e) {
      Outputs.error = String((e && e.message) || e);
      // Logged for the operator; the caller still gets one refusal body (the mcp/auth.ts rule).
      console.error('[dbt:lesson]', Outputs.error);
      Outputs.failed();
    }
  })();
}
